\begin{tikzpicture}[x=7mm,y=7mm,line cap=round,line join=round]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{locusBlue}{HTML}{268CFF}
\path[use as bounding box] (-2.2,-0.7) rectangle (7,10.6);
\coordinate (A) at (1,3);
\coordinate (B) at (3,9);
\coordinate (C) at (2,6);
% An illustrative point on the locus; its coordinates are not a source given.
\coordinate (P) at (5,7);
\draw[black,line width=0.5pt,->] (-2,0)--(6.8,0);
\draw[black,line width=0.5pt,->] (0,-0.4)--(0,10.3);
\node[black,anchor=north,yshift=-3pt] at (6.8,0) {$x$};
\node[black,anchor=south east,xshift=-3pt] at (0,10.3) {$y$};
\draw[black,line width=0.4pt,dashed] (0,6)--(C)--(2,0);
\draw[black,line width=0.4pt,dashed] (A)--(B)--(P)--cycle;
\draw[locusBlue,line width=0.8pt] plot[domain=0:360,samples=181,variable=\t] ({2+sqrt(10)*cos(\t)},{6+sqrt(10)*sin(\t)});
\node[black,anchor=east,xshift=-3pt] at (0,6) {\special{dvisvgm:raw <g data-graph-text="tick">}$6$\special{dvisvgm:raw </g>}};
\node[black,anchor=north,yshift=-3pt] at (2,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$2$\special{dvisvgm:raw </g>}};
\fill[black] (C) circle[radius=1.6pt];
\fill[locusBlue] (P) circle[radius=1.6pt];
\draw[draw=locusBlue,fill=white,line width=0.8pt] (A) circle[radius=2.2pt];
\draw[draw=locusBlue,fill=white,line width=0.8pt] (B) circle[radius=2.2pt];
\node[black,anchor=south east,xshift=-1pt,yshift=4pt] at (C) {$(2,6)$};
\node[black,anchor=north,yshift=-6pt,align=center] at (A) {$A$\\$(1,3)$};
\node[black,anchor=south,xshift=3pt,yshift=5pt] at (B) {$B(3,9)$};
\node[black,anchor=west,xshift=4pt] at (P) {$P$};
\end{tikzpicture}
